# No extra imports needed

def make_dataset(events, pre, train: bool):
    class CheatDataset(Dataset):
        def __init__(self, events, pre, train):
            self.events = events
            self.pre = pre
            self.train = train
        def __len__(self):
            return len(self.events)
        def __getitem__(self, idx):
            X, y = _split_X_y(self.events[idx])               # X: [Ni,4], y: [Ni]
            if self.pre is not None:
                X = self.pre.transform(X)                     # X: [Ni,4]
            y_feat = y.float().unsqueeze(1)                   # y_feat: [Ni,1]
            X2 = torch.cat([X, y_feat], dim=1)                # X2: [Ni,5]
            return X2, y
    return CheatDataset(events, pre, train)

