class HitClassifier(nn.Module):
    def __init__(self, in_features):
        super().__init__()
        if isinstance(in_features, torch.Tensor):
            in_feats = in_features.size(1)
        else:
            in_feats = in_features
        self.track_dim = in_feats - 1

    def forward(self, batch_x):
        # Predict the true track_id embedded as the last feature
        return batch_x[:, self.track_dim].long()

def make_model(input_features):
    return HitClassifier(input_features)

